"use strict";
(()=>{const KEY="hj-domain-journeys-v1",STAGES=["日常世界","冒険への誘い","ためらい","メンターとの出会い","最初の境界線","試練・仲間・敵","最も深い場所へ","最大の試練","報酬","帰路","復活","宝を持って帰還"],text=(v,n)=>String(v??"").replace(/[<>"'`]/g,"").trim().slice(0,n),defaults=[{id:"work",name:"仕事",icon:"💼",stage:STAGES[0],cycle:1,theme:"",updatedAt:""},{id:"life",name:"生活",icon:"🏠",stage:STAGES[0],cycle:1,theme:"",updatedAt:""},{id:"money",name:"お金",icon:"¥",stage:STAGES[0],cycle:1,theme:"",updatedAt:""},{id:"relations",name:"人間関係",icon:"🤝",stage:STAGES[0],cycle:1,theme:"",updatedAt:""},{id:"dream",name:"夢・挑戦",icon:"✨",stage:STAGES[0],cycle:1,theme:"",updatedAt:""}];function read(){try{return JSON.parse(localStorage.getItem(KEY)||"null")}catch{return null}}function normalize(){const current=read();if(!Array.isArray(current)||!current.length){localStorage.setItem(KEY,JSON.stringify(defaults));return defaults}const safe=current.map((j,i)=>({id:text(j?.id,100)||`journey-${i+1}`,name:text(j?.name,24)||"旅",icon:text(j?.icon,4)||"🧭",stage:STAGES.includes(j?.stage)?j.stage:STAGES[0],cycle:Math.max(1,Math.min(99,+j?.cycle||1)),theme:text(j?.theme,160),updatedAt:text(j?.updatedAt,60)}));localStorage.setItem(KEY,JSON.stringify(safe));return safe}normalize();document.getElementById("editProfile")?.addEventListener("click",normalize,true);document.addEventListener("click",e=>{if(e.target?.dataset?.role!=="save")return;const card=e.target.closest(".journey-card"),cards=[...document.querySelectorAll(".journey-card")],index=cards.indexOf(card),journeys=normalize(),before=journeys[index],stage=card?.querySelector('[data-role="stage"]')?.value,cycle=card?.querySelector('[data-role="cycle"]');if(before?.stage===STAGES[STAGES.length-1]&&stage===STAGES[0]&&cycle&&(+cycle.value||1)<=+before.cycle)cycle.value=Math.min(99,(+before.cycle||1)+1)},true)})();